def _collect_leaves(node, acc=[]):
    if not node.get('children'):
        acc.append(node['name'])
        return acc
    for child in node['children']:
        _collect_leaves(child, acc)
    return acc


def leaf_names(tree):
    return _collect_leaves(tree)

