from leaves import leaf_names


def test_leaf_names_two_independent_trees():
    tree1 = {'name': 'root1', 'children': [{'name': 'a'}, {'name': 'b'}]}
    tree2 = {'name': 'root2', 'children': [{'name': 'c'}]}
    assert leaf_names(tree1) == ['a', 'b']
    assert leaf_names(tree2) == ['c']


def test_leaf_names_single_leaf():
    assert leaf_names({'name': 'only'}) == ['only']
